//! Capture filters (design section 5.3). Filters 1–5 are evaluated here in
//! order; filter 6 (duplicate) is handled by `HistoryStore::capture`.

use crate::model::Payload;
use crate::settings::Settings;

/// Pasteboard marker types that mean "do not record this" (nspasteboard.org).
pub const CONCEALED_MARKERS: [&str; 3] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
];

/// Everything about a pasteboard change other than the payload itself.
#[derive(Clone, Debug, Default)]
pub struct CaptureMeta {
    /// The pasteboard change count for this change.
    pub change_count: i64,
    /// Change count produced by our own paste engine, if any.
    pub own_change_count: Option<i64>,
    /// All type identifiers present on the pasteboard.
    pub types: Vec<String>,
    /// Bundle id of the frontmost app when the change was seen.
    pub app_bundle_id: Option<String>,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum DropReason {
    OwnWrite,
    TypeDisabled,
    Concealed,
    IgnoredApp,
    TooLarge,
    Empty,
}

pub fn has_concealed_marker<S: AsRef<str>>(types: &[S]) -> bool {
    types.iter().any(|t| CONCEALED_MARKERS.contains(&t.as_ref()))
}

pub fn is_ignored_app(settings: &Settings, bundle_id: Option<&str>) -> bool {
    match bundle_id {
        Some(id) => settings.ignore_apps.iter().any(|a| a.eq_ignore_ascii_case(id)),
        None => false,
    }
}

/// Filters 1–4, which need only metadata. Run this before reading the
/// payload so that concealed or ignored content is never read at all.
pub fn precheck(settings: &Settings, meta: &CaptureMeta, kind: crate::model::ClipKind) -> Result<(), DropReason> {
    if meta.own_change_count == Some(meta.change_count) {
        return Err(DropReason::OwnWrite);
    }
    if !settings.kind_enabled(kind) {
        return Err(DropReason::TypeDisabled);
    }
    if has_concealed_marker(&meta.types) {
        return Err(DropReason::Concealed);
    }
    if is_ignored_app(settings, meta.app_bundle_id.as_deref()) {
        return Err(DropReason::IgnoredApp);
    }
    Ok(())
}

/// Decide whether a pasteboard change should be stored (filters 1–5).
pub fn evaluate(settings: &Settings, meta: &CaptureMeta, payload: &Payload) -> Result<(), DropReason> {
    precheck(settings, meta, payload.kind())?;
    let limit = match payload {
        Payload::Text { .. } => Some(settings.max_text_bytes),
        Payload::Image { .. } => Some(settings.max_image_bytes),
        Payload::Files { .. } => None,
    };
    if limit.is_some_and(|l| payload.byte_size() > l) {
        return Err(DropReason::TooLarge);
    }
    if payload.is_empty() {
        return Err(DropReason::Empty);
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn meta() -> CaptureMeta {
        CaptureMeta { change_count: 10, ..Default::default() }
    }

    #[test]
    fn accepts_plain_text() {
        assert_eq!(evaluate(&Settings::default(), &meta(), &Payload::text("hi")), Ok(()));
    }

    #[test]
    fn own_write_is_skipped_first() {
        let mut m = meta();
        m.own_change_count = Some(10);
        m.types = vec![CONCEALED_MARKERS[0].into()];
        assert_eq!(evaluate(&Settings::default(), &m, &Payload::text("hi")), Err(DropReason::OwnWrite));
        m.own_change_count = Some(9);
        assert_eq!(evaluate(&Settings::default(), &m, &Payload::text("hi")), Err(DropReason::Concealed));
    }

    #[test]
    fn disabled_type() {
        let s = Settings { capture_images: false, ..Default::default() };
        assert_eq!(evaluate(&s, &meta(), &Payload::Image { png: vec![1] }), Err(DropReason::TypeDisabled));
        assert_eq!(evaluate(&s, &meta(), &Payload::text("x")), Ok(()));
    }

    #[test]
    fn each_concealed_marker_drops() {
        for marker in CONCEALED_MARKERS {
            let mut m = meta();
            m.types = vec!["public.utf8-plain-text".into(), marker.into()];
            assert_eq!(evaluate(&Settings::default(), &m, &Payload::text("pw")), Err(DropReason::Concealed));
        }
    }

    #[test]
    fn ignored_app_ships_with_password_managers() {
        let mut m = meta();
        m.app_bundle_id = Some("com.1password.1password".into());
        assert_eq!(evaluate(&Settings::default(), &m, &Payload::text("pw")), Err(DropReason::IgnoredApp));
        m.app_bundle_id = Some("com.apple.Safari".into());
        assert_eq!(evaluate(&Settings::default(), &m, &Payload::text("pw")), Ok(()));
    }

    #[test]
    fn size_caps() {
        let s = Settings { max_text_bytes: 4, max_image_bytes: 2, ..Default::default() };
        assert_eq!(evaluate(&s, &meta(), &Payload::text("1234")), Ok(()));
        assert_eq!(evaluate(&s, &meta(), &Payload::text("12345")), Err(DropReason::TooLarge));
        assert_eq!(evaluate(&s, &meta(), &Payload::Image { png: vec![0; 3] }), Err(DropReason::TooLarge));
    }

    #[test]
    fn empty_is_dropped() {
        assert_eq!(evaluate(&Settings::default(), &meta(), &Payload::text("  \n")), Err(DropReason::Empty));
        assert_eq!(evaluate(&Settings::default(), &meta(), &Payload::Files { paths: vec![] }), Err(DropReason::Empty));
    }
}
